bounded_host_request.command:
set -eu
cid=gace-createvdobot-videobot-poll-1
test "$(docker inspect "$cid" --format '{{.State.Running}}')" = true || exit 61
test "$(docker ps --filter label=com.docker.compose.project=gace-createvdobot --filter label=com.docker.compose.service=videobot-poll -q | wc -l)" -eq 1 || exit 62
docker exec -i -w /opt/videobot "$cid" node --input-type=module <<'JS'
import pg from 'pg';
import {readFileSync} from 'node:fs';
import {writeFile,mkdir,access} from 'node:fs/promises';
import {setDefaultResultOrder} from 'node:dns';
import {setDefaultAutoSelectFamily} from 'node:net';
import {createCreatorTelegramFetch} from '/opt/videobot/src/runtime/creatorEgress.mjs';
import {createTelegramBotApi} from '/opt/videobot/src/telegram/botApi.mjs';
setDefaultResultOrder('ipv4first');setDefaultAutoSelectFamily(false);
const e=process.env;
const pw=readFileSync('/run/secrets/videobot_db_password','utf8').trim();
const token=readFileSync('/run/secrets/videobot_telegram_token','utf8').trim();
const pool=new pg.Pool({host:e.VIDEOBOT_DB_HOST,user:e.VIDEOBOT_DB_USER,database:e.VIDEOBOT_DB_NAME,password:pw,max:1,connectionTimeoutMillis:5000,idleTimeoutMillis:1000});
const network=createCreatorTelegramFetch();
const api=createTelegramBotApi({token,fetchImpl:network.fetch,timeoutMs:25000});
const bad=(code)=>{const x=new Error(code);x.code=code;throw x;};
try{
 const q=await pool.query("SELECT a.delivery_key AS old_key,a.listing_id,a.revision AS old_revision,a.topic_id,a.status AS old_status,a.free_message_ids AS old_free,a.paid_message_id AS old_paid,b.delivery_key AS new_key,b.status AS new_status,b.free_message_ids AS new_free,b.paid_message_id AS new_paid,l.revision AS current_revision,l.status AS listing_status FROM videobot_post_receipts a JOIN videobot_listings l ON l.listing_id=a.listing_id JOIN videobot_post_receipts b ON b.listing_id=a.listing_id AND b.revision=l.revision AND b.topic_id=a.topic_id WHERE a.paid_message_id=4691 AND a.free_message_ids=ARRAY[4689,4690]::bigint[]");
 if(q.rowCount!==1)bad('CLEANUP_RECEIPT_PAIR_MISSING');
 const r=q.rows[0];
 if(r.old_status!=='sent'||r.new_status!=='sent'||r.current_revision!==r.old_revision+1||r.old_paid!=4691||r.new_paid==4691||!Array.isArray(r.new_free)||r.new_free.length!==2||r.new_free.some(v=>[4689,4690,4691].includes(Number(v)))||!['published','paused'].includes(r.listing_status))bad('CLEANUP_SALE_INTEGRITY_FAILED');
 if(!e.VIDEOBOT_VIDEO_SALE_THREAD_ID||Number(e.VIDEOBOT_VIDEO_SALE_THREAD_ID)!==Number(r.topic_id))bad('CLEANUP_TOPIC_CHANGED');
 const sale=await pool.query("SELECT COUNT(*)::integer AS n FROM videobot_stars_ledger WHERE delivery_key=$1 AND kind='paid'",[r.old_key]);
 if(sale.rows[0].n<1)bad('OLD_PAID_PRESERVATION_NOT_VERIFIED');
 const me=await api('getMe',{});
 if(String(me?.username||'').toLowerCase()!=='createvdobot')bad('WRONG_BOT');
 const chatId=-1002373696859;
 const stateDir=(e.VIDEOBOT_VIDEO_WORK_ROOT||'/var/lib/videobot/media-work')+'/replacements/legacy-4689-4691';
 await mkdir(stateDir,{recursive:true,mode:0o700});
 for(const mid of [4689,4690]){
   const intent=stateDir+'/delete-'+mid+'.intent';
   const ack=stateDir+'/delete-'+mid+'.ack';
   let hasAck=false;
   try{await access(ack);hasAck=true;}catch{}
   if(hasAck){console.log('ORIGINAL_FREE_ALREADY_REMOVED_'+mid+'=PASS');continue;}
   try{await writeFile(intent,'authorized replacement cleanup for legacy free message '+mid+'\n',{flag:'wx',mode:0o600});}
   catch{bad('OLD_DELETE_OUTCOME_UNKNOWN_'+mid);}
   const deleted=await api('deleteMessage',{chat_id:chatId,message_id:mid});
   if(deleted!==true)bad('TELEGRAM_DELETE_NOT_ACKNOWLEDGED_'+mid);
   await writeFile(ack,'Telegram deleteMessage success: '+mid+'\n',{flag:'wx',mode:0o600});
   console.log('ORIGINAL_FREE_REMOVED_'+mid+'=PASS');
 }
 console.log('ORIGINAL_PURCHASED_PAID_4691_PRESERVED=PASS');
 console.log('NEW_NATIVE_GALLERY_AND_PAID_RECEIPTS_PRESERVED=PASS');
}catch(err){
 console.error('LEGACY_CLEANUP_STOP='+String(err.code||'SAFE_STOP'));
 process.exitCode=1;
}finally{await network.close();await pool.end();}
JS
